style.css:
@-moz-document domain("roblox.com") {
body {
        background: radial-gradient(circle at top, #d80000, #990000);
        background-image: url("https://i.imgur.com/9mUvX0M.jpg"); /* Hosted version of your star background */
        background-repeat: repeat;
        background-size: cover;
        background-attachment: fixed;
        color: white !important;
        font-family: 'Segoe UI', sans-serif;
    }

    .navbar, .footer, .header, .container, .content {
        background-color: rgba(0, 0, 0, 0.6) !important;
        border-radius: 10px;
    }

    a {
        color: #ffdddd !important;
    }

    a:hover {
        color: #ffffff !important;
        text-shadow: 0 0 5px #ff4d4d;
    }

    /* Optional: Make buttons glow */
    button, .btn-primary {
        background-color: #ff3333 !important;
        border: none;
        box-shadow: 0 0 10px #ff6666;
        color: white !important;
    }

    button:hover, .btn-primary:hover {
        background-color: #ff0000 !important;
        box-shadow: 0 0 15px #ff9999;
    }
}
